mapper.sql:
from cms_chk_tmpl t left join mst_equip_class c on c.class_id = t.equip_class_id

  t.use_yn = #{useYn}
  and (t.tmpl_cd like #{keyword} escape '\' or t.tmpl_nm ilike #{keyword} escape '\')

mapper.select:
select order by
t.tmpl_nm desc t.target_kind desc c.class_cd desc nulls last t.use_yn desc t.tmpl_cd desc ,
t.tmpl_id limit #{page.size} offset #{page.offset}

mapper.update:
update cms_chk_tmpl
   set tmpl_nm = #{f.tmplNm}, equip_class_id = #{f.equipClassId}, use_yn = #{f.useYn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tmpl_id = #{id} and row_ver = #{f.rowVer}

update cms_chk_tmpl_item
   set seq = #{v.seq}, item_nm = #{v.itemNm}, method_text = #{v.methodText}, judge_type = #{v.judgeType}, lsl = #{v.lsl},
       usl = #{v.usl}, unit_nm = #{v.unitNm}, scale = #{v.scale}, required_yn = #{v.requiredYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where item_id = #{v.itemId} and tmpl_id = #{tmplId}

mapper.sql:
select * from (select p.plan_id, p.plan_cd, p.plan_nm, coalesce(e.equip_cd, a.asset_cd) as target_cd, t.tmpl_cd, p.exec_mode,
                      u.user_nm as assignee_nm, p.use_yn, p.next_due_date,
                      coalesce(e.plant_cd, (select e2.plant_cd from mst_asset_install i join mst_equip e2 on e2.equip_id = i.equip_id
                                             where i.asset_id = p.asset_id and i.removed_at is null and i.void_yn = 'N' limit 1)) as plant_cd


    p.use_yn = #{useYn}
    and p.equip_id = #{equipId}
    and (p.plan_cd like #{keyword} escape '\' or p.plan_nm ilike #{keyword} escape '\'
        or e.equip_cd like #{keyword} escape '\' or a.asset_cd like #{keyword} escape '\')
) x
x.plant_cd = #{plantCd}

mapper.update:
update cms_pm_plan
   set next_due_date = #{next}, last_done_date = coalesce(#{lastDone}, last_done_date),
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where plan_id = #{id}

update cms_pm_plan
   set next_due_usage = #{next}, last_done_date = coalesce(#{lastDone}, last_done_date),
       last_done_usage = coalesce(#{lastDoneUsage}, last_done_usage),
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where plan_id = #{id}

mapper.insert:
insert into cms_chk_result (comp_cd, run_id, seq, item_nm, method_text, judge_type, lsl, usl, unit_nm, scale, required_yn,
                            created_by, updated_by)
select hb_current_comp(), #{runId}, i.seq, i.item_nm, i.method_text, i.judge_type, i.lsl, i.usl, i.unit_nm, i.scale,
       i.required_yn, #{by}, #{by}
  from cms_chk_tmpl_item i where i.tmpl_id = #{tmplId}

mapper.sql:
 from cms_chk_run r
 left join cms_pm_plan p on p.plan_id = r.plan_id
 left join cms_mwo m on m.mwo_id = r.mwo_id
 left join mst_equip e on e.equip_id = r.equip_id
 left join mst_phys_asset a on a.asset_id = r.asset_id
where r.due_date >= #{from} and r.due_date <= #{to}
  and r.status in #{s}
  and p.exec_mode = #{execMode}
  and r.plan_id = #{planId}
  and r.equip_id = #{equipId}
  and (p.plan_cd like #{keyword} escape '\' or p.plan_nm ilike #{keyword} escape '\'
       or e.equip_cd like #{keyword} escape '\' or a.asset_cd like #{keyword} escape '\')
  and coalesce(e.plant_cd, (select e2.plant_cd from mst_asset_install i join mst_equip e2 on e2.equip_id = i.equip_id
                              where i.asset_id = r.asset_id and i.removed_at is null and i.void_yn = 'N' limit 1)) = #{plantCd}

mapper.update:
update cms_chk_result
   set value_num = #{valueNum}, value_text = #{valueText}, judge = #{judge}, remark = #{remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where run_id = #{runId} and seq = #{seq}

update cms_chk_run
   set status = #{status}, performed_at = #{performedAt}, performed_by = #{performedBy}, result = #{result},
       skip_reason_cd = #{skipReasonCd}, skip_reason = #{skipReason}, done_usage = #{doneUsage},
       floor_worker_id = #{floorWorkerId}, floor_terminal_id = #{floorTerminalId}, floor_req_id = #{floorReqId},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where run_id = #{id} and status = 'OPEN' and row_ver = #{rowVer}

mapper.select:
select ,
       (select count(*) from cms_chk_result x where x.run_id = r.run_id) as item_cnt

 where r.status = 'OPEN' and p.exec_mode = 'CHECK' and e.plant_cd = #{plantCd}
   and r.equip_id in #{id}
 order by r.due_date, e.equip_cd, r.run_id
 limit #{limit}
